<script setup lang="ts">
import {computed,ref,shallowRef,watch} from 'vue'
import {ApiError} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {formatTime} from '@/core/time'
import {useResource} from '@/core/use-resource'
import AsyncState from '@/ui/AsyncState.vue'
import CursorPager from '@/ui/CursorPager.vue'
import {statusLabel} from '../devices/api'
import {alarmLabel} from '../devices/page-alarm-status'
import {validOtaName} from './ota-management-metadata-api'
import type {OtaFirmware} from './ota-read-api'
import {otaVersionDistributionTransport,type OtaVersionDistributionTransport,type OtaVersionBucket,type OtaVersionDevicesQuery,type OtaReportedVersion} from './ota-version-distribution-api'
const props=withDefaults(defineProps<{firmware:OtaFirmware;active:boolean;summary?:boolean;transport?:OtaVersionDistributionTransport}>(),{transport:()=>otaVersionDistributionTransport})
const emit=defineEmits<{more:[]}>()
const readable=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&props.firmware.projectId===projectId.value&&can('ota:read')&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const bucket=shallowRef<OtaVersionBucket>(),opened=ref(false),keyword=ref(''),status=ref<''|'INACTIVE'|'ONLINE'|'OFFLINE'>(''),order=ref<OtaVersionDevicesQuery['order']>('CREATED_ASC'),validation=ref('')
const query=shallowRef<OtaVersionDevicesQuery>()
const distribution=useResource(async signal=>{const project=projectId.value,firmware=props.firmware,transport=props.transport;const binding=await transport.binding(project,firmware.id,signal);signal.throwIfAborted();return binding.executionBinding===null?null:transport.read(project,firmware,signal)})
const displayedBuckets=computed(()=>props.summary?distribution.data.value?.buckets.slice(0,5):distribution.data.value?.buckets)
const devices=useResource(signal=>{if(!query.value)throw new Error('请选择版本');return props.transport.devices(projectId.value,props.firmware,query.value,signal)})
const forbidden=computed(()=>!readable.value||distribution.error.value instanceof ApiError&&[401,403].includes(distribution.error.value.status))
const deviceForbidden=computed(()=>!readable.value||devices.error.value instanceof ApiError&&[401,403].includes(devices.error.value.status))
const reasons:Record<string,string>={NO_CURRENT_MODEL:'尚无当前物模型',PROPERTY_MISSING:'当前物模型未定义版本属性',PROPERTY_NOT_TEXT:'版本属性不是文本',SOURCE_VERSION_UNKNOWN:'上报来源版本未确认',SOURCE_MODEL_MISMATCH:'上报来源与当前物模型不一致',CONTRACT_MISMATCH:'上报属性契约不一致',SOURCE_REVISION_UNKNOWN:'上报修订未确认'}
function label(row:OtaVersionBucket){return row.state==='NO_VALUE'?'未上报':row.state==='UNCONFIRMED'?'未确认':row.version===''?'（空字符串）':row.version!}
function fact(version:OtaReportedVersion){return version.state==='VALUE'?(version.rawValue===''?'（空字符串）':version.rawValue):version.state==='NO_VALUE'?'未上报':`未确认：${reasons[version.reason!]}`}
function close(){opened.value=false;bucket.value=undefined;query.value=undefined;devices.clear();validation.value=''}
function updateOpened(value:boolean){if(!value)close()}
function reload(){close();distribution.clear();if(readable.value&&props.active)void distribution.reload()}
function loadDevices(){devices.clear();if(readable.value&&props.active&&opened.value&&query.value)void devices.reload()}
function show(row:OtaVersionBucket){if(!readable.value||!props.active||!distribution.data.value?.buckets.includes(row))return;close();bucket.value=row;keyword.value='';status.value='';order.value='CREATED_ASC';query.value=Object.freeze({bucket:row.id,order:'CREATED_ASC',page:1,limit:20});opened.value=true;loadDevices()}
function filter(){if(!query.value||!readable.value)return;validation.value='';if(keyword.value!==''&&(keyword.value.length>128||!validOtaName(keyword.value))){validation.value='关键词须为不超过128个字符的有效文本';return}query.value=Object.freeze({...query.value,keyword:keyword.value||undefined,status:status.value||undefined,order:order.value,page:1});loadDevices()}
function turn(page:number){if(!query.value||!Number.isInteger(page)||page<1||page>2147483647||devices.loading.value)return;query.value=Object.freeze({...query.value,page});loadDevices()}
function resize(limit:number){if(!query.value||![20,50,100,200].includes(limit)||devices.loading.value)return;query.value=Object.freeze({...query.value,limit,page:1});loadDevices()}
watch([()=>projectId.value,()=>props.firmware,()=>session.user?.accountId,readable,()=>props.active,()=>props.transport],reload,{immediate:true,flush:'sync'})
</script>
<template><section v-if="active" class="ota-version-distribution"><div class="distribution-heading"><h3>版本分布</h3><el-button :loading="distribution.loading.value" :disabled="!readable" @click="reload">刷新</el-button></div><p class="help">按设备实际上报的版本属性统计。版本相同不代表已经完成升级，升级结果以实际记录为准。</p>
<AsyncState :forbidden="forbidden" :loading="distribution.loading.value" :error="distribution.error.value" @retry="reload"><p v-if="distribution.data.value===null">历史版本未设置模块和版本属性，无法读取版本分布。</p><template v-else-if="distribution.data.value"><p>设备总数：{{distribution.data.value.totalDevices}}</p><p class="help">版本属性：{{distribution.data.value.versionProperty}} · 分布观察时间：{{formatTime(distribution.data.value.observedAt)}}</p><el-empty v-if="!distribution.data.value.buckets.length" description="此设备类型尚无设备" :image-size="48"/><el-table v-else :data="displayedBuckets" border><el-table-column label="设备版本" min-width="180"><template #default="{row}"><span class="version-value">{{label(row)}}</span><el-tag v-if="row.target" size="small">目标版本</el-tag></template></el-table-column><el-table-column prop="count" label="设备数" min-width="100"/><el-table-column label="占比" min-width="140"><template #default="{row}"><el-progress v-if="row.percentage!==null" :percentage="Number(row.percentage)" :format="()=>`${row.percentage}%`"/><span v-else>—</span></template></el-table-column><el-table-column v-if="!summary" label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="show(row)">查看设备</el-button></template></el-table-column></el-table><el-button v-if="summary" link type="primary" @click="emit('more')">查看更多版本</el-button></template></AsyncState>
<el-dialog :model-value="opened" title="查看设备" width="1000px" class="ota-version-devices-dialog" :close-on-click-modal="false" @update:model-value="updateOpened"><template v-if="bucket&&query"><p class="version-value">设备版本：{{label(bucket)}}</p><form class="device-filters" @submit.prevent="filter"><el-input v-model="keyword" aria-label="版本设备关键词" placeholder="设备名称、标识或业务标识" maxlength="128"/><el-select v-model="status" aria-label="版本设备状态" placeholder="不限设备状态"><el-option label="不限设备状态" value=""/><el-option label="未激活" value="INACTIVE"/><el-option label="在线" value="ONLINE"/><el-option label="离线" value="OFFLINE"/></el-select><el-select v-model="order" aria-label="版本设备排序"><el-option label="创建时间正序" value="CREATED_ASC"/><el-option label="创建时间倒序" value="CREATED_DESC"/><el-option label="最近活跃优先" value="ACTIVE_DESC"/><el-option label="设备名称正序" value="NAME_ASC"/></el-select><el-button native-type="submit" :loading="devices.loading.value">查询</el-button></form><p v-if="validation" role="alert">{{validation}}</p>
<AsyncState :forbidden="deviceForbidden" :loading="devices.loading.value" :error="devices.error.value" @retry="loadDevices"><template v-if="devices.data.value"><p>共 {{devices.data.value.total}} 台设备</p><p class="help">设备观察时间：{{formatTime(devices.data.value.observedAt)}}。此列表单独读取，数量可能与此前分布不同。</p><el-empty v-if="!devices.data.value.items.length" description="当前条件无设备" :image-size="48"/><el-table v-else :data="devices.data.value.items" border><el-table-column label="设备名称" min-width="130"><template #default="{row}"><router-link v-if="can('device:read')" :to="`/devices/${row.deviceId}`">{{row.name}}</router-link><span v-else>{{row.name}}</span></template></el-table-column><el-table-column prop="deviceKey" label="设备标识" min-width="150"/><el-table-column label="业务标识" min-width="120"><template #default="{row}">{{row.businessKey??'—'}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}">{{statusLabel(row.status)}}</template></el-table-column><el-table-column label="上报版本" min-width="170"><template #default="{row}"><span class="version-value">{{fact(row.version)}}</span></template></el-table-column><el-table-column label="上报时间" min-width="160"><template #default="{row}">{{formatTime(row.version.occurredAt)}}</template></el-table-column><el-table-column label="告警" min-width="110"><template #default="{row}">{{alarmLabel(row.alarm.state==='UNKNOWN'?undefined:row.alarm.state)}}</template></el-table-column></el-table><CursorPager :page="query.page" :limit="query.limit" :total="devices.data.value.total" :sizes="[20,50,100,200]" :loading="devices.loading.value" @update:page="turn" @update:limit="resize"/></template></AsyncState></template></el-dialog></section></template>
<style scoped>.distribution-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.distribution-heading h3{font-size:17px;font-weight:500}.help{color:var(--tl-muted);font-size:12px;line-height:20px}.version-value{white-space:pre-wrap;overflow-wrap:anywhere}.el-tag{margin-left:8px}.device-filters{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.device-filters .el-input{width:260px}.device-filters .el-select{width:160px}@media(max-width:600px){.device-filters .el-input,.device-filters .el-select{width:100%}}</style>
